+  font-size: 0.75rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.08em;
+  color: var(--accent);
+  margin-bottom: 0.35rem;
+}
+
+.help-text {
+  color: var(--text-muted);
+  font-size: 0.9rem;
+  margin: 0 0 0.85rem;
+}
+
+.options {
+  display: grid;
+  grid-template-columns: 1fr;
+  gap: 0.5rem;
+  margin-top: 0.25rem;
+}
+@media (min-width: 480px) {
+  .options { grid-template-columns: 1fr 1fr; }
+}
+
+.option {
+  display: flex;
+  align-items: flex-start;
+  gap: 0.65rem;
+  padding: 0.7rem 0.85rem;
+  background: rgba(255,255,255,0.02);
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  cursor: pointer;
+  transition: background 120ms ease, border-color 120ms ease;
+}
+.option:hover { background: rgba(110,168,255,0.08); border-color: var(--border-strong); }
+.option:has(input:checked) {
+  background: rgba(47,129,247,0.12);
+  border-color: var(--accent-strong);
+}
+.option:has(input:focus-visible) {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.option input[type="checkbox"] {
+  /* Keep native control accessible; size it up for readability */
+  width: 1.1rem;
+  height: 1.1rem;
+  margin: 0.15rem 0 0;
+  accent-color: var(--accent-strong);
+  flex: 0 0 auto;
+}
+
+.option span.label-text {
+  color: var(--text);
+  font-size: 0.97rem;
+}
+
+.actions {
+  display: flex;
+  gap: 0.75rem;
+  align-items: center;
+  flex-wrap: wrap;
+  margin-top: 0.5rem;
+}
+
+button[type="submit"] {
+  background: var(--accent-strong);
+  color: #fff;
+  border: 1px solid var(--accent-strong);
+  font-weight: 600;
+  font-size: 1rem;
+  padding: 0.7rem 1.25rem;
+  border-radius: 8px;
+  cursor: pointer;
+  transition: background 120ms ease, transform 120ms ease;
+}
+button[type="submit"]:hover { background: #4593ff; }
+button[type="submit"]:active { transform: translateY(1px); }
+button[type="submit"]:focus-visible {
+  outline: 3px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.status {
+  margin: 0;
+  padding: 0.85rem 1rem;
+  border-radius: 8px;
+  background: var(--surface-2);
+  border: 1px solid var(--border);
+  color: var(--text);
+}
+.status.is-success {
+  border-color: rgba(63,185,80,0.45);
+  background: rgba(63,185,80,0.10);
+}
+
+@media (prefers-reduced-motion: reduce) {
+  * { transition: none !important; }
+}
+
+@media (forced-colors: active) {
+  .option { border: 1px solid CanvasText; }
+  .option:has(input:checked) { border: 2px solid Highlight; }
+  button[type="submit"] { border: 1px solid ButtonText; }
+}
+
')

